import { forEachChild, parse, } from 'unbash';
import { extractBinary } from './modules.js';
const spawningBinaries = new Set(['c8', 'cross-env', 'retry-cli']);
export const toShellCommand = (argv) => argv.map(arg => `'${arg.replaceAll("'", `'\\''`)}'`).join(' ');
export const getCommandWords = (node) => node.args.filter((arg) => arg.type === 'Word');
export const collectCommands = (root) => {
    const commands = [];
    const visit = (node) => {
        if (node.type === 'Command')
            commands.push(node);
        if (!isScriptExpansion(node))
            forEachChild(node, visit);
    };
    visit(root);
    return commands;
};
export const isScriptExpansion = (node) => node.type === 'CommandExpansion' || node.type === 'ProcessSubstitution' || node.type === 'ArithmeticCommandExpansion';
export const getScriptCommands = (script) => {
    if (!script)
        return [];
    const out = [];
    try {
        for (const statement of parse(script).commands) {
            for (const node of collectCommands(statement.command)) {
                const text = node.name?.value;
                if (!text)
                    continue;
                const binary = extractBinary(text);
                const words = getCommandWords(node);
                if (spawningBinaries.has(binary)) {
                    const rest = words
                        .filter(word => word.text !== '--')
                        .map(word => word.text)
                        .join(' ');
                    out.push(...getScriptCommands(rest));
                }
                else
                    out.push({ binary, args: words.map(word => word.value) });
            }
        }
    }
    catch {
        return [];
    }
    return out;
};
